"""Assess accurate palm subchain separately from failed whole-hand FK predictions."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'docs/2026-10-12/stability_adapter_2/results';PHASE=BASE/'palm_support_two_axis_fk_v2'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    paths=[PHASE/'analysis.json',BASE/'palm_support_runtime_fk_v1/analysis.json',Path(__file__).resolve()];inputs={str(p):sha(p) for p in paths};whole=json.loads(paths[0].read_text());runtime=json.loads(paths[1].read_text());rows=[r for r in whole['rows'] if r['mode']=='exp_sum'];palm=[e for r in rows for e in r['body_errors'] if e['body']=='LH:palm'];arm=[e for r in rows for e in r['body_errors'] if e['body'].startswith(('L_Thorax','L_Shoulder','L_Elbow','L_Wrist'))];out=PHASE/'palm_scope_assessment.json';assert not out.exists()
    result=dict(input_sha256=inputs,palm_samples=len(palm),max_palm_origin_error_mm=max(e['position_error_mm'] for e in palm),max_palm_rotation_error_rad=max(e['rotation_error_rad'] for e in palm),max_arm_origin_error_mm=max(e['position_error_mm'] for e in arm),max_arm_rotation_error_rad=max(e['rotation_error_rad'] for e in arm),four_sample_max_palm_anchor_error_mm=max(r['palm_anchor_prediction_error_mm'] for r in runtime['samples']),whole_hand_gate_passed=False,four_geometric_proposals_PD_target_bounds_pass=all(r['base_plus_dq_within_native_limits'] and r['base_plus_dq_initial_main_offsets_within0p3'] for r in runtime['samples']),checks=dict(exact24_saved_palm_samples=len(palm)==24,all24_palm_gates_pass=all(e['position_error_mm']<=.1 and e['rotation_error_rad']<=.001 for e in palm),whole_hand_failure_retained=not runtime['all_saved_prediction_gates_passed'] and not any(v['prediction_gate_passed'] for v in whole['summary']),inputs_unchanged=all(sha(p)==h for p,h in inputs.items())),scope='specific accurate palm/arm subchain evidence; whole hand still failed for four two-axis hypotheses. Current measured finger-body geometry may be used without predicting finger q; no runtime controller or PD/contact certification')
    assert all(result['checks'].values());out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='input_sha256'},indent=2))
